#include <set>
struct Compare {
  bool descending;
  bool operator()(int a, int b) const { return descending ? a > b : a < b; }
};

int main() {
  std::set<int, Compare> values(Compare{true});
  values.insert(1);
  values.insert(3);
  return *values.begin() == 3 ? 0 : 1;
}
